from fastapi.responses import HTMLResponse


def updates_page():
    return HTMLResponse(r'''<!doctype html><html lang="en" class="nct-shell-loading"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NCT · Updates and Recovery</title><style id="nct-shell-bootstrap">html.nct-shell-loading body{visibility:hidden}</style>
<style>:root{--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--blue:#74c7ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui}header{padding:20px 4vw}main{max-width:1100px;margin:auto;padding:32px 24px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;margin:20px 0}h1{font-size:28px}h2{font-size:20px}p,li{color:var(--muted)}button{background:var(--panel);color:var(--text);border:1px solid var(--blue);border-radius:7px;padding:12px 18px;cursor:pointer}button:disabled{opacity:.6;cursor:wait}[hidden]{display:none!important}progress{width:100%}</style><script src="/assets/nct-session.js"></script></head><body><header>NCT · Network Correlation &amp; Triage</header><main><h1>Updates and Recovery</h1>
<section class="panel" data-guide-context="nct-updates"><h2>Open the recovery workspace</h2><p>Use the independent recovery workspace to upload an offline NCT update, review its checks, install it, or restore the saved pre-update version. It stays available while NCT restarts.</p><ol><li>Open the workspace while signed in. NCT starts it and verifies that it is ready.</li><li>Upload the single NCT update <code>.tar.gz</code> file and review the exact release and source-build checks. Validation does not replace NCT.</li><li>Choose Apply after current scan and collection work has finished. The helper checks the stopped data, independently verifies a cold backup, and then replaces NCT.</li><li>For updates, repairs and restored installations, verify an existing NCT account in the workspace. A proven new empty installation uses its first normal Administrator sign-in instead. Return to NCT after the build, health, sign-in and retained-evidence checks pass.</li></ol><p>If an update fails, the workspace keeps the result and offers Restore saved backup. Restore returns to the backup time and preserves evidence collected after the backup separately.</p><button id="openRecovery" type="button">Open update and recovery workspace</button><progress id="launchProgress" hidden aria-label="Starting recovery workspace"></progress><p id="updateStatus" role="status" aria-live="polite"></p></section>
<section class="panel"><h2>Deployment support</h2><p>The trusted recovery helper must be installed once on the NCT host. The application does not receive Docker control. If NCT cannot start, use the host recovery launcher to open the same workspace with a short-lived access code.</p><p>This first adapter supports one Docker or Docker Compose NCT container with a dedicated bind-mounted evidence directory. Kubernetes updates remain unavailable until the separate controller and storage acceptance checks are completed.</p></section></main><script>
document.getElementById('openRecovery').onclick=async()=>{const button=document.getElementById('openRecovery'),status=document.getElementById('updateStatus'),progress=document.getElementById('launchProgress');button.disabled=true;progress.hidden=false;status.textContent='Starting the independent recovery workspace and checking readiness…';try{const response=await fetch('/api/updates/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),value=await response.json();if(!response.ok)throw Error(value.detail||'Recovery workspace did not start');const palette={};for(const key of ['--bg','--panel','--line','--text','--muted','--blue'])palette[key]=getComputedStyle(document.documentElement).getPropertyValue(key).trim();location.assign(value.url+'&palette='+encodeURIComponent(JSON.stringify(palette)))}catch(error){status.textContent=error.message;button.disabled=false;progress.hidden=true}};
</script></body></html>''')


def console_page():
    return HTMLResponse(r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NCT Recovery Console</title><style>
:root{color-scheme:dark;--bg:#09131c;--panel:#112330;--line:#304955;--text:#e8f2f6;--muted:#abc0cb;--blue:#74c7ff}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui}header{border-bottom:1px solid var(--line);padding:20px max(24px,5vw)}main{max-width:1120px;margin:auto;padding:24px}h1{font-size:26px}h2{font-size:19px}p,small{color:var(--muted)}section,details{background:var(--panel);border:1px solid var(--line);padding:20px;border-radius:10px;margin:18px 0}summary{cursor:pointer}fieldset{border:0;padding:0;margin:0;min-width:0}button,input{font:inherit;color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:9px 12px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button.primary{border-color:var(--blue)}label{display:block;margin:12px 0}input{max-width:100%;display:block}progress{width:100%;accent-color:var(--blue)}.journey{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.journey h2{font-size:15px;margin:0}.journey p{margin:8px 0 0}.step-activity{border-left:3px solid var(--blue);padding:0 14px;margin-bottom:20px}.step-activity p{margin:8px 0}@media(max-width:800px){.journey{grid-template-columns:1fr;gap:12px}main{padding:18px}section,details{padding:16px}}.actions{display:flex;gap:10px;flex-wrap:wrap}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{width:30%}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 system-ui}.warning{border-left:4px solid #d7ab47}a{color:var(--blue)}:focus-visible{outline:2px solid var(--blue);outline-offset:3px}</style></head><body><header><strong>NCT</strong> · Independent Recovery Console</header><main><h1>Updates and Recovery</h1><p>This workspace remains available while NCT stops or restarts. All actions are recorded with the operator. Closing the browser does not cancel an update.</p><p id="status" role="status" aria-live="polite">Connecting to recovery helper…</p><p id="actionError" role="alert" hidden></p><p id="connectionStatus" role="status" hidden></p><button id="retryStatus" type="button" hidden>Retry connection</button><progress id="busy" hidden aria-label="Recovery operation running"></progress>
<section id="access" hidden><h2>Host recovery access</h2><p>This emergency code is needed when opening recovery without a current NCT handoff. Normally, sign in to NCT and open Updates & Recovery to enter automatically. If NCT cannot start, ask the NCT host administrator for the one-use code from the recovery launcher; it expires after two minutes. This is separate from your NCT account password.</p><form id="accessForm"><label>Recovery access code<input id="code" type="password" autocomplete="off" required></label><button>Open recovery workspace</button></form></section>
<div id="workspace" hidden><section class="journey" aria-label="Update progress"><div><h2>Current step</h2><p id="currentStep" role="status"></p></div><div><h2>NCT observation</h2><p id="nctObservation"></p></div><div><h2>What to do next</h2><p id="nextAction"></p></div></section><fieldset id="workspaceControls"><section><h2>1. Upload and validate</h2><p>Choose a trusted NCT update <code>.tar.gz</code> package. Its image checksum is included. Validation checks the exact installed build, image identity, saved data compatibility and space. It loads the release image locally but does not replace or stop NCT. Original terminal deployment ZIP packages use the terminal installer.</p><form id="uploadForm"><label>Offline update package<input id="package" type="file" accept=".gz,.tgz" required></label><button id="upload" class="primary">Upload and validate package</button></form><p id="uploadStatus" role="status"></p></section>
<section><h2>2. Review and apply</h2><div class="step-activity"><p id="reviewActivity" role="status"></p><progress id="activityProgress" hidden aria-label="Measured work in the current step"></progress><p id="activityMeasurement"></p><p id="activityAge"></p><p id="connectionAge"></p></div><div class="table-wrap" data-nct-table-mode="static"><table><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody id="checks"></tbody></table></div><p id="detail"></p><button id="apply" class="primary" disabled>Apply validated update</button><p>Apply stops NCT, checks unfinished work, verifies schema compatibility again, makes and independently restores a cold backup, then replaces NCT. Unresolved work blocks the update.</p></section>
<section id="verifySection" hidden><h2 id="verifyHeading">3. Verify sign-in and finish</h2><p>Use an existing NCT account. The password is sent only to your local NCT instance for this check and is never saved by the recovery helper. Collection and processing remain paused until verification succeeds. NCT then performs its final restart and resumes only the services paused for this update. This check confirms the running NCT version accepts your existing account; it does not sign your browser into NCT. Normal NCT sign-in may be needed after returning.</p><form id="verifyForm"><label>NCT username<input id="username" autocomplete="username" required></label><label>NCT password<input id="password" type="password" autocomplete="current-password" required></label><button id="verifyButton">Verify sign-in</button></form><p id="verifyFeedback" role="status" aria-live="polite">The password field clears when submitted. Wait here for the sign-in and final restart result.</p><progress id="verifyProgress" hidden aria-label="Checking sign-in and final restart"></progress></section>
<section id="repairSection" hidden><h2>Review unfinished-work repair</h2><p>NCT is stopped for this review. The check preserves completed evidence and valid waiting scans. Apply only after reviewing the affected work and blockers. Restored collection remains paused for review in NCT.</p><pre id="repairSummary"></pre><div class="actions"><button id="applyRepair" disabled>Apply reviewed work repair</button><button id="cancelRepair">Resume NCT without repair</button></div></section>
<details><summary>Recovery controls and diagnostics</summary><p>Start, stop and restart affect only the configured NCT container. Review diagnostics before recovery. The host distinguishes an actual backup restore from resuming the original installation without a backup swap. Older records may require administrator review.</p><div class="actions"><button data-action="diagnose">Investigate NCT</button><button data-action="verify-backup">Verify saved backup</button><button id="prepareRepair">Check unfinished work for repair</button><button data-action="start">Start NCT</button><button data-action="stop">Stop NCT</button><button data-action="restart">Restart NCT</button><button id="rollback">Restore saved backup</button><button id="export">Export diagnostic summary</button></div><pre id="diagnostic" role="status"></pre></details>
<details><summary>Operator Guide</summary><ol><li>Transfer the single NCT update .tar.gz file to the computer running this browser, then choose it here. The full deployment ZIP is for the host installer.</li><li>Wait for upload and package checks. NCT continues running during validation.</li><li>Compare the installed release with the proposed release before choosing Apply.</li><li>NCT stops while the helper checks saved data and unfinished work.</li><li>The helper creates a cold backup, checks its checksum, and extracts a separate verification copy.</li><li>Byte counts describe only the named step, not the entire update. Steps without a known total show an indeterminate bar.</li><li>The helper installs the release and checks readiness and retained evidence.</li><li>Enter an existing NCT account when prompted. Clearing the password field means it was submitted, not that it was rejected.</li><li>Wait for the final restart and an explicit completion result before returning to NCT.</li><li>After returning, sign in normally if prompted, check the installed release, open an older scan in Scan History and save its XML. Keep the original full deployment ZIP for host recovery.</li></ol><p>How to use this: follow Upload → Review → Apply → Verify. Keep this page open to see saved progress. If the connection drops, wait for automatic status retry or choose Retry connection. The last checked information remains visible with actions disabled until fresh status arrives. Retry only reads status; it never repeats an update or restore. Use a new NCT handoff or emergency host code only when access has expired. The helper retains the operation.</p><p>How NCT uses this: the verified backup protects the existing accounts and evidence before the new release writes to them. A saved receipt connects the operator, package, original installation and verification results. Recovery identifies whether it will restore a backup or reconcile the original installation. Only an actual backup restore returns evidence to the backup time; later data is preserved separately. Older records may need administrator review.</p><p>After a host interruption, the helper pauses for explicit recovery review. It never guesses that an incomplete update succeeded. If recovery cannot prove the required container identity or backup, it stops and explains the failure.</p></details><button id="return">Return to NCT and close recovery workspace</button></fieldset></div></main><script>
const $=id=>document.getElementById(id);let current={},applicationUrl='',working=false,reconnecting=false,verifying=false,refreshing=false,activityClock=null;
function recoveryText(){return current.recovery_guidance==='original_reconciliation'?'Resume the original NCT installation. No backup will be swapped.':current.recovery_guidance==='backup_restore'?'Restore the verified pre-update backup. Evidence collected after that backup will be preserved separately.':'The saved history does not establish whether the replacement wrote data. Ask the host administrator to review recovery before continuing.'}
function updateActivityTimes(){if(!activityClock)return;const activity=activityClock.activity,now=activityClock.server+(Date.now()-activityClock.client)/1000;const age=Number.isFinite(activity.updated_at)?Math.max(0,Math.floor(now-activity.updated_at)):null,elapsed=Number.isFinite(activity.started_at)?Math.max(0,Math.floor(now-activity.started_at)):null;$('activityAge').textContent=(activity.active&&elapsed!==null?'Time in this step: '+elapsed+' seconds. ':'')+(age!==null?'Last work update '+age+' seconds ago.':'No work-update time reported by this helper.')+(activity.active===true&&age!==null&&age>=30?' Work has not reported a new checkpoint recently; keep this page open and review diagnostics if it continues.':'')+' A connected helper does not prove work is advancing.';}
function showActivity(state){const activity=current.activity||{},measured=Number.isSafeInteger(activity.completed)&&Number.isSafeInteger(activity.total)&&activity.completed>=0&&activity.total>0&&activity.completed<=activity.total&&['bytes','files'].includes(activity.unit);$('currentStep').textContent=activity.active&&typeof activity.label==='string'?activity.label:current.detail||'Choose an update package to begin.';$('reviewActivity').textContent=$('currentStep').textContent;const runtime=state.runtime;$('nctObservation').textContent=runtime&&runtime.available===true&&typeof runtime.running==='boolean'?(runtime.running?'NCT container is running; application readiness is checked separately.':'NCT container is stopped.'):'NCT container state is unavailable. This does not establish application health.';$('nextAction').textContent=verifying?'Wait here for sign-in verification and the final restart.':current.phase==='validated'?'Review the installed and proposed release, then choose Apply.':current.phase==='awaiting_sign_in'?'Enter an existing NCT account below to finish the update.':current.phase==='awaiting_restore_sign_in'?'Verify your existing account after recovery. '+recoveryText():['failed','interrupted'].includes(current.phase)?'Review diagnostics before recovery. '+recoveryText():['complete','restored'].includes(current.phase)?'Return to NCT and check a retained evidence download.':current.phase==='repair_review'?'Review the affected records and blockers below. Apply only the reviewed repair, or resume without repair.':current.phase==='awaiting_repair_sign_in'?'Verify your existing NCT account to finish the reviewed repair.':current.phase==='idle'?'Choose the NCT update .tar.gz file.':'Keep this workspace open. Closing it does not cancel host work.';$('verifyHeading').textContent=current.phase==='awaiting_restore_sign_in'?(current.recovery_outcome&&current.recovery_outcome.backup_swapped===true?'3. Verify sign-in after backup restoration':current.recovery_outcome&&current.recovery_outcome.backup_swapped===false?'3. Verify sign-in after original installation recovery':'3. Verify sign-in after recovery'):'3. Verify sign-in and finish';const bar=$('activityProgress');bar.hidden=activity.active!==true;if(measured){bar.max=activity.total;bar.value=activity.completed}else bar.removeAttribute('value');$('activityMeasurement').textContent=activity.active?(measured?activity.completed.toLocaleString()+' of '+activity.total.toLocaleString()+' '+activity.unit+' processed for this step.':'This step has no measurable total; no percentage is estimated.'):'No active work step reported.';$('activityAge').textContent=Number.isFinite(activity.updated_at)?'Last work update: '+new Date(activity.updated_at*1000).toLocaleString()+'. A connected helper does not prove work is advancing.':'No work-update time reported by this helper.';$('rollback').textContent=current.recovery_guidance==='original_reconciliation'?'Resume original NCT':'Review recovery / restore';$('connectionAge').textContent='Last helper response: '+new Date().toLocaleTimeString();activityClock={activity,server:Number.isFinite(state.observed_at)?state.observed_at:Date.now()/1000,client:Date.now()};updateActivityTimes()}
const fragment=new URLSearchParams(location.hash.slice(1)),handoff=fragment.get('handoff');history.replaceState(null,'',location.pathname);try{const serialized=fragment.get('palette')||sessionStorage.getItem('nct-recovery-palette')||'{}',palette=JSON.parse(serialized);for(const key of ['--bg','--panel','--line','--text','--muted','--blue'])if(typeof palette[key]==='string'&&palette[key].length<100&&CSS.supports('color',palette[key]))document.documentElement.style.setProperty(key,palette[key]);sessionStorage.setItem('nct-recovery-palette',serialized)}catch(_){}
async function api(route,body,method='POST'){const response=await fetch('/api'+route,{method,headers:{'Content-Type':'application/json','X-NCT-Recovery':'1'},...(method==='GET'?{}:{body:JSON.stringify(body||{})})});const value=await response.json();if(!response.ok){const error=Error(value.detail||'Recovery action failed');error.accessRequired=route==='/status'&&value.access_required===true&&response.status===403;throw error}return value}
function message(text){$('status').textContent=text}async function action(work){if(working)return;working=true;$('actionError').hidden=true;$('actionError').textContent='';$('busy').hidden=false;try{await work()}catch(error){$('actionError').textContent=error.message;$('actionError').hidden=false;message(error.message)}finally{working=false;$('busy').hidden=true}}
function render(state){if(!state||typeof state!=='object'||Array.isArray(state)||!state.operation||typeof state.operation!=='object'||Array.isArray(state.operation)||typeof state.operation.phase!=='string'||typeof state.application_url!=='string'||typeof state.actor!=='string')throw Error('Recovery helper returned an invalid status.');const summary=state.operation.repair_summary;if(summary!==undefined&&summary!==null&&(typeof summary!=='object'||Array.isArray(summary)||!Number.isInteger(summary.affected_count)||summary.affected_count<0||!Number.isInteger(summary.preserved_scan_queue)||summary.preserved_scan_queue<0||typeof summary.safe_to_apply!=='boolean'||!Array.isArray(summary.categories)||!Array.isArray(summary.blockers)||!summary.blockers.every(item=>typeof item==='string')||!summary.categories.every(group=>group&&typeof group.category==='string'&&Array.isArray(group.actions)&&group.actions.every(item=>item&&typeof item.action==='string'&&typeof item.record==='string'))))throw Error('Recovery helper returned an invalid repair summary.');const failure=state.operation.apply_failure;if(failure!==undefined&&(failure===null||typeof failure!=='object'||Array.isArray(failure)||typeof failure.phase!=='string'||typeof failure.detail!=='string'||!Number.isFinite(failure.recorded_at)))throw Error('Recovery helper returned an invalid saved update failure.');current=state.operation;applicationUrl=state.application_url;$('workspace').hidden=false;$('access').hidden=true;const rows=[['Operator',state.actor],['Current saved step',current.activity&&current.activity.active&&typeof current.activity.label==='string'?current.activity.label:({idle:'Ready',validated:'Ready to apply',fence_intent:'Stopping NCT',backup_verified:'Backup verified',replace_intent:'Replacing NCT',candidate_created:'Starting the new version',awaiting_sign_in:'Verify your NCT sign-in',awaiting_restore_sign_in:'Verify sign-in after recovery',awaiting_repair_sign_in:'Verify NCT after repair',repair_review:'Review unfinished work',repair_intent:'Repairing unfinished work',repair_verified:'Repair verified',release_intent:'Finishing verification',complete:'Update complete',failed:'Update failed — review recovery result',restored:({work_repair:'Unfinished-work repair complete',preview_cancel:'Preview closed without repair',backup_restore:'Saved backup restored',original_reconciliation:'Original installation resumed without a backup swap',original_restart_unknown_history:'Original installation resumed; earlier write history unknown'})[current.completion_kind]||'Recovery complete',interrupted:'Needs recovery review',restore_intent:'Recovering the original installation',restore_swap_intent:'Returning to the backup time'})[current.phase]||'Working'],['Installed to proposed release',(current.installed_build_id||'Installed release not reported')+' to '+(current.build_id||'No package validated')],['Commit',current.build_commit||'—'],['Last verified running build',current.running_build_id||'Not yet verified'],['Running build commit',current.running_build_commit||'Not yet verified'],...(failure?[['Update failure that started recovery',failure.detail+' · saved at '+new Date(failure.recorded_at*1000).toLocaleString()]]:[]),['Cold backup',current.backup_verified?'Verified · '+new Date(current.backup_at*1000).toLocaleString():current.activity&&current.activity.active&&current.activity.step==='backup_create'?'Creating — verification follows':current.backup_path||current.activity&&['backup_hash','backup_extract','backup_compare'].includes(current.activity.step)?'Awaiting independent verification':'No verified backup reported'],['Preserved post-backup data',current.quarantine_path||'No restore performed'],['Saved backup file',current.backup_path||'Not yet created'],['Retained evidence',current.evidence_verified?'Verified':'Not yet checked'],['Existing-account sign-in',current.controller_sign_in_verified?'Verified':'Not yet checked']];$('checks').replaceChildren();for(const [key,value] of rows){const row=document.createElement('tr');for(const text of [key,value]){const cell=document.createElement('td');cell.textContent=text;row.append(cell)}$('checks').append(row)}$('detail').textContent=current.detail||'Upload a package to begin.';$('apply').disabled=current.phase!=='validated';$('verifySection').hidden=!verifying&&!['awaiting_sign_in','awaiting_restore_sign_in','awaiting_repair_sign_in'].includes(current.phase);$('busy').hidden=!working&&['idle','validated','complete','restored','failed','interrupted','awaiting_sign_in','awaiting_restore_sign_in','awaiting_repair_sign_in'].includes(current.phase);showActivity(state);message(current.detail||'Recovery workspace ready.')}
async function refresh(){if(refreshing)return;refreshing=true;try{render(await api('/status',null,'GET'));reconnecting=false;$('workspaceControls').disabled=false;$('connectionStatus').hidden=true;$('retryStatus').hidden=true;const canUpload=['idle','validated','complete','restored','failed'].includes(current.phase);$('upload').disabled=!canUpload;$('package').disabled=!canUpload;$('repairSection').hidden=current.phase!=='repair_review';if(current.repair_summary){const summary=current.repair_summary,lines=[`Work records needing repair: ${summary.affected_count}`,`Valid waiting scans preserved: ${summary.preserved_scan_queue}`,`Can apply: ${summary.safe_to_apply?'Yes':'Blocked'}`,...(summary.blockers||[])];for(const group of summary.categories||[]){lines.push('',group.category.replaceAll('_',' ')+':');for(const item of group.actions)lines.push('  '+item.record+' · '+item.action.replaceAll('_',' '))}$('repairSummary').textContent=lines.join('\n');$('applyRepair').disabled=!summary.safe_to_apply||!summary.affected_count}if(current.phase==='repair_review'){$('busy').hidden=true;message('Review the unfinished-work plan. NCT remains stopped.')}}catch(error){$('workspaceControls').disabled=true;$('busy').hidden=true;if(error.accessRequired){reconnecting=false;$('workspace').hidden=true;$('access').hidden=false;$('connectionStatus').hidden=true;$('retryStatus').hidden=true;message('Recovery access has expired or is missing. Reopen from NCT, or use a fresh host recovery code.')}else{reconnecting=true;$('access').hidden=true;$('connectionStatus').hidden=false;$('retryStatus').hidden=false;$('connectionStatus').textContent='Recovery status is unavailable. Last checked information is shown with actions disabled. Retrying does not repeat an update or recovery action. '+error.message;message('Waiting for a fresh recovery status.')}}finally{refreshing=false}}
async function exchange(code){try{await api('/exchange',{code});$('code').value='';await refresh()}catch(error){await refresh();throw error}}
$('retryStatus').onclick=()=>{if(!working)refresh()};
$('accessForm').onsubmit=event=>{event.preventDefault();action(()=>exchange($('code').value))};
$('uploadForm').onsubmit=event=>{event.preventDefault();action(async()=>{const file=$('package').files[0];if(!file)throw Error('Choose an NCT update package');$('currentStep').textContent='Uploading the selected update package';$('nextAction').textContent='Wait for upload and validation before reviewing or applying.';$('uploadStatus').textContent='Uploading and validating. NCT continues running.';try{await new Promise((resolve,reject)=>{const request=new XMLHttpRequest();request.open('POST','/api/upload');request.setRequestHeader('X-NCT-Recovery','1');request.upload.onprogress=event=>{if(event.lengthComputable){$('uploadStatus').textContent='Upload '+Math.round(event.loaded/event.total*100)+'% · validation follows';if(event.loaded===event.total){$('currentStep').textContent='Upload sent — checking the package';$('nextAction').textContent='Wait for package validation. NCT has not been replaced.'}}};request.onload=()=>{try{const value=JSON.parse(request.responseText);if(request.status>=400)throw Error(value.detail);resolve(value)}catch(error){reject(error)}};request.onerror=()=>reject(Error('Upload interrupted. Reopen recovery workspace to inspect status.'));request.send(file)})}catch(error){$('uploadStatus').textContent='Upload or validation failed: '+error.message;throw error}$('uploadStatus').textContent='Package checked. NCT has not changed. Review the release and choose Apply to install it.';await refresh()})};
$('apply').onclick=()=>action(async()=>{if(!confirm('Stop NCT, verify its cold backup, and install '+current.build_id+'?'))return;await api('/apply',{plan_digest:current.plan_digest});await refresh()});
$('rollback').onclick=()=>action(async()=>{if(!['original_reconciliation','backup_restore'].includes(current.recovery_guidance)&&!confirm('Administrator review required: the earlier write history is unknown. Export and inspect diagnostics first. Continue only if you have reviewed this recovery as the host administrator.'))return;if(!confirm(recoveryText()+' Run the host recovery checks?'))return;await api('/rollback',{confirm:'RESTORE'});await refresh()});
$('prepareRepair').onclick=()=>action(async()=>{if(!confirm('Stop NCT and make a verified cold backup to review unfinished work? NCT stays stopped until you apply the repair or resume without changes.'))return;await api('/prepare-repair');await refresh()});
$('applyRepair').onclick=()=>action(async()=>{if(!confirm('Apply this exact unfinished-work repair? Completed evidence and valid waiting scans are preserved. Collection remains paused for review.'))return;await api('/apply-repair',{plan_digest:current.plan_digest});await refresh()});
$('cancelRepair').onclick=()=>action(async()=>{if(!confirm('Resume NCT without repair? Its existing queues and automation may start again.'))return;await api('/cancel-repair',{confirm:'RESUME'});await refresh()});
$('verifyForm').onsubmit=event=>{event.preventDefault();return action(async()=>{verifying=true;const password=$('password').value;$('password').value='';$('verifyButton').disabled=true;$('verifyButton').textContent='Checking sign-in…';$('verifyProgress').hidden=false;$('verifyFeedback').textContent='Checking sign-in and finishing NCT’s restart. Please wait—you will return to NCT automatically. The password field has been cleared after submission.';let confirmed=false;try{const verified=await api('/verify-sign-in',{username:$('username').value,password});if(!verified||typeof verified.url!=='string'||!verified.url||!verified.operation||!['complete','restored'].includes(verified.operation.phase)||verified.operation.controller_sign_in_verified!==true)throw Error('Recovery returned an incomplete sign-in result.');confirmed=true;$('verifyFeedback').textContent='Sign-in and final restart verified. Returning to NCT…';await api('/close');location.assign(verified.url)}catch(error){$('verifyFeedback').textContent=(confirmed?'Sign-in and final restart passed, but returning to NCT could not be completed. Reopen NCT to check the result; do not apply the update again. ':'Sign-in completion could not be confirmed. Check the current recovery status before trying again. ')+error.message;throw Error($('verifyFeedback').textContent)}finally{verifying=false;$('verifyProgress').hidden=true;$('verifyButton').disabled=false;$('verifyButton').textContent='Verify sign-in'}})};
document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>action(async()=>{const name=button.dataset.action;if(['stop','restart'].includes(name)&&!confirm(name+' the configured NCT instance?'))return;$('diagnostic').textContent=JSON.stringify(await api('/'+name,{},name==='diagnose'?'GET':'POST'),null,2);await refresh()}));
$('export').onclick=()=>action(async()=>{const value=await api('/diagnose',null,'GET'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='nct-recovery-summary.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('return').onclick=()=>action(async()=>{const value=await api('/close');location.assign(value.url)});
if(handoff)action(()=>exchange(handoff));else refresh();setInterval(()=>{updateActivityTimes();if(document.visibilityState!=='hidden'&&(!working||verifying)&&(!$('workspace').hidden||reconnecting))refresh()},3000);
</script></body></html>''')
